const IDO = () => {
  const { address: account } = useAccount();
  const config = useConfig();
  const [bnbAmount, setBnbAmount] = useState('');
  const [tokenAmount, setTokenAmount] = useState('0');
  const [loading, setLoading] = useState(false);
  const [refAddress, setRefAddress] = useState(null);


  // Mock token price (replace with actual price from contract)
  const tokenPrice = 0.0001; // BNB per token
  const { data: fixedFee } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'FIXED_FEE',
  });
  const { data: tokensPerBnb } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'TOKENS_PER_BNB',
  });
  const handleBnbChange = (e) => {
    const value = e.target.value;
    setBnbAmount(value);
    
    // Tính token amount dựa trên TOKENS_PER_BNB từ contract
    if (value && tokensPerBnb) {
      const tokens = (parseFloat(value) * Number(tokensPerBnb));
      // Format số token để hiển thị đầy đủ, không dùng scientific notation
      const formattedTokens = tokens.toLocaleString('fullwide', { useGrouping: false, maximumFractionDigits: 0 });
      setTokenAmount(formattedTokens);
    } else {
      setTokenAmount('0');
    }
  };
  

  const handleBuy = async () => {
    if (!account) {
      toast.error('Vui lòng kết nối ví');
      return;
    }

    if (!bnbAmount || parseFloat(bnbAmount) <= 0) {
      toast.error('Vui lòng nhập số lượng BNB hợp lệ');
      return;
    }

    try {
      setLoading(true);
      const bnbValue = parseEther(bnbAmount);
      const feeAmount = fixedFee || parseEther('0.008'); // Use contract fee or fallback
      const totalValue = bnbValue + feeAmount;
      
      toast.info('Đang xử lý giao dịch...');
      
      const txHash = await writeContract(config, {
        abi: idoContractAbi,
        address: idoContractAddress,
        functionName: 'buyTokens',
        args: [refAddress || zeroAddress],
        value: totalValue,
      });

      toast.info('Đang chờ xác nhận giao dịch...');
      const receipt = await waitForTransactionReceipt(config, { 
        hash: txHash 
      });

      // Call backend API
      try {
        await axios.post('http://localhost:3001/ido/purchase', {
          wallet: account,
          bnbPaid: parseFloat(bnbAmount),
          tokensReceived: parseFloat(tokenAmount),
          referrer: refAddress,
          txHash: txHash
        });
      } catch (apiError) {
        console.warn('Backend API call failed:', apiError);
        // Continue even if backend fails
      }

      toast.success('Mua token thành công!');
      setBnbAmount('');
      setTokenAmount('0');
    } catch (err) {
      console.error('Buy error:', err);
      if (err.message.includes('user rejected') || err.message.includes('User rejected')) {
        toast.error('Giao dịch bị hủy');
      } else if (err.message.includes('insufficient funds')) {
        toast.error('Không đủ BNB trong ví');
      } else {
        toast.error('Mua token thất bại: ' + (err.shortMessage || err.message));
      }
    } finally {
      setLoading(false);
    }
  };
  
  

useEffect(() => {
  const params = new URLSearchParams(window.location.search);
  const ref = params.get('ref');
  if (ref) setRefAddress(ref);
}, []);


  return (
    <IDOContainer>
      <Title>Buy $PAI Tokens</Title>
      <InputGroup>
        <Label>Amount in BNB</Label>
        <Input
          type="number"
          value={bnbAmount}
          onChange={handleBnbChange}
          placeholder="Enter BNB amount"
          min="0"
          step="0.01"
        />
      </InputGroup>

      <TokenInfo>
        <Label>You will receive:</Label>
        <div>{tokenAmount} $PAI tokens</div>
      </TokenInfo>

      <BuyButton
        onClick={handleBuy}
        disabled={loading || !bnbAmount || !account}
      >
        {loading ? 'Processing...' : 'Buy Tokens'}
      </BuyButton>
    </IDOContainer>
  );
};

